python3 -I -c "
import json, re
def strict_ans(s):
    s=s[-300:] if len(s)>300 else s
    m=re.findall(r'#### (\-?[0-9\.\,]+)', s)
    if not m: return None
    return m[-1].replace(',','').replace('\$','')
def flexible_ans(s):
    s=s[-300:] if len(s)>300 else s
    m=re.findall(r'(\-?[0-9\.\,]+)', s)
    for a in reversed(m):
        if a not in ('','.'):
            return a.replace(',','')
    return None
for step in [0,10,30,60]:
    rows=[json.loads(l) for l in open(f'results/dapo_gsm8k_seed42/val_generations/{step}.jsonl')]
    n=len(rows)
    strict=sum(1 for r in rows if strict_ans(r['output'])==str(r['gts']))
    flex=sum(1 for r in rows if flexible_ans(r['output'])==str(r['gts']))
    # how many have a ### answer at all
    has_hash=sum(1 for r in rows if re.search(r'#### ', r['output'][-300:]))
    print(f'step {step}: strict={strict/n:.4f} flex={flex/n:.4f} has_####={has_hash/n:.4f}')
"

