python3 -I -c "
import json, re
# Find rollouts where flexible reward seems WRONG vs the boxed answer
def flex(s):
    s=s[-300:] if len(s)>300 else s
    m=re.findall(r'(\-?[0-9\.\,]+)', s)
    for a in reversed(m):
        if a not in ('','.'):
            return a.replace(',','')
    return None
def boxed(s):
    m=re.findall(r'boxed\{([^}]*)\}', s)
    if m: return m[-1].strip()
    return None
def hash_ans(s):
    s=s[-300:] if len(s)>300 else s
    m=re.findall(r'#### (\-?[0-9\.\,]+)', s)
    if m: return m[-1].replace(',','')
    return None
rows=[json.loads(l) for l in open('results/dapo_gsm8k_seed42/rollouts/60.jsonl')]
mismatch=0
for r in rows:
    out=r['output']; gt=str(r['gts'])
    b=boxed(out); h=hash_ans(out); f=flex(out)
    # cases where boxed answer is correct but reward (flexible) gave 0 => reward signal wrong
    if b is not None and (b==gt or b.replace(' ','')==gt) and r.get('acc')==0:
        mismatch+=1
        if mismatch<=3:
            print('=== BUG: boxed correct but acc=0; gt=',gt,'boxed=',b,'flex=',f)
            print(out[-250:])
print('total boxed-correct-but-zero-reward:', mismatch)
"

